//! Host entry stubs for guest native methods.
//!
//! ART (or any JVM) calls a native method through a plain function pointer.
//! Every stub in the pool loads its own index and jumps to a common entry
//! that spills the argument registers and calls a64b_tramp_dispatch(index,
//! saved_registers, stack_arguments) (see jni.rs). The pool is static code
//! (generated by build.rs), so no executable memory has to be generated at run time.
// SPDX-License-Identifier: GPL-2.0-or-later

#[cfg(target_arch = "x86_64")]
std::arch::global_asm!(include_str!(concat!(env!("OUT_DIR"), "/trampoline.s")), options(att_syntax));
#[cfg(target_arch = "aarch64")]
std::arch::global_asm!(include_str!(concat!(env!("OUT_DIR"), "/trampoline.s")));

extern "C" {
    static a64b_tramp_pool: u8;
}

pub const MAX_TRAMPOLINES: u32 = 4096;
#[cfg(target_arch = "aarch64")]
pub const TRAMP_STRIDE: usize = 8;
#[cfg(target_arch = "aarch64")]
pub const GPR_COUNT: usize = 8;
#[cfg(target_arch = "x86_64")]
pub const TRAMP_STRIDE: usize = 16;
#[cfg(target_arch = "x86_64")]
pub const GPR_COUNT: usize = 6;

/// Address of stub `index`.
pub fn tramp_address(index: u32) -> *mut std::ffi::c_void {
    unsafe { (&a64b_tramp_pool as *const u8).add(index as usize * TRAMP_STRIDE) as *mut std::ffi::c_void }
}
